import 'package:flutter/material.dart'; import '../core/services/api_client.dart'; import '../core/services/session.dart'; import 'home_screen.dart'; import 'rider_screen.dart'; import '../core/services/push_service.dart'; class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginState();} class _LoginState extends State<LoginScreen>{final email=TextEditingController();final password=TextEditingController();bool loading=false;String? error;Future<void> login()async{setState(()=>loading=true);try{final d=await ApiClient.post('/auth/login',{'email':email.text,'password':password.text});final role=d['user']?['role']??'customer';if(role!='customer'&&role!='rider'){throw Exception('This mobile app is for customer and rider accounts. Staff should use the dedicated FoodHub web portal.');}await Session.save(d['token'],userRole:role);await PushService.initialize();if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Session.role=='rider'?const RiderScreen():const HomeScreen()));}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Card(child:Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('FoodHub',style:Theme.of(c).textTheme.displaySmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Smart food commerce'),const SizedBox(height:28),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.red))),const SizedBox(height:20),FilledButton(onPressed:loading?null:login,child:Text(loading?'Signing in…':'Sign in'))])))))));}}